package com.theone.series;
import android.content.Intent;import android.widget.GridView;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.*;import org.junit.runner.RunWith;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class SeriesLoadingIsolationTest {
 @Test public void openingSeasonsDoesNotWaitForCatalogWorker()throws Exception{Intent intent=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK).putExtra("series_test_mode",true);UiDevice device=UiDevice.getInstance(InstrumentationRegistry.getInstrumentation());AtomicReference<CountDownLatch> gate=new AtomicReference<>();try(ActivityScenario<MainActivity> scenario=ActivityScenario.launch(intent)){scenario.onActivity(a->gate.set(a.pauseCatalogWorkerForTest()));AtomicBoolean blocked=new AtomicBoolean();for(int n=0;n<30&&!blocked.get();n++){scenario.onActivity(a->blocked.set(a.isCatalogWorkerBlockedForTest()));Thread.sleep(50);}assertTrue(blocked.get());scenario.onActivity(a->{GridView grid=a.findViewById(1020);grid.performItemClick(grid.getChildAt(0),0,grid.getAdapter().getItemId(0));});assertTrue(device.wait(Until.hasObject(By.text("Seizoenen en afleveringen")),5000));device.findObject(By.text("Seizoenen en afleveringen")).click();assertTrue("Seasons load while catalog worker is blocked",device.wait(Until.hasObject(By.text("Seizoen 1")),5000));device.pressBack();}finally{if(gate.get()!=null)gate.get().countDown();}}
}
